import React, { useEffect, useMemo, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { ClerkProvider, SignedIn, SignedOut, SignIn, UserButton, useAuth, useReverification } from '@clerk/clerk-react'
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome'
import { faArrowLeft, faCamera, faCheck, faChevronLeft, faChevronRight, faChild, faCircleInfo, faFaceSmile, faGripVertical, faLock, faMagnifyingGlass, faPen, faPlay, faPlus, faTrashCan, faTriangleExclamation, faUsersGear, faVideo, faXmark } from '@fortawesome/free-solid-svg-icons'
import { MediaPlayer, MediaProvider, Track } from '@vidstack/react'
import { defaultLayoutIcons, DefaultVideoLayout } from '@vidstack/react/player/layouts/default'
import '@vidstack/react/player/styles/default/theme.css'
import '@vidstack/react/player/styles/default/layouts/video.css'
import './style.css'
import './player.css'

const key=import.meta.env.VITE_CLERK_PUBLISHABLE_KEY
const api=import.meta.env.VITE_API_URL
const colors=['#e50914','#0f9d8f','#6b38d1','#1773e8','#e67e22','#27952c','#c2185b','#0086a8']
const profilePictures=['amy.png','apple-jack.png','bingo.png','blaze.png','blue.png','bluey.png','bucket-n-shovel.png','bunnie.png','daphane.png','donald.png','drake.png','fluttershy.png','fred.png','gigi.png','goofy.png','josh.png','julie-su.png','knuckles.png','magenta.png','mailbox.png','manic.png','max.png','mickey.png','pinky-pie.png','rainbow-dash.png','rarity.png','rotor.png','sally.png','salt-n-pepper.png','scoobydoo.png','shadow.png','shaggy.png','soapy.png','sonia.png','sonic.png','superman-fleisher.png','tails.png','twilight-sparkle.png','velma.png']
const genres=['Action','Adventure','Cartoon','Live Action','Animation','Family','Suspense','Science Fiction','Fantasy','Sports','Romance','Comedy','Home Videos']
const seriesCredits={bluey:{label:'Wikipedia',url:'https://en.wikipedia.org/wiki/List_of_Bluey_episodes'},'blues-clues':{label:'Wikipedia',url:"https://en.wikipedia.org/wiki/List_of_Blue's_Clues_episodes"},'scooby-doo-where-are-you':{label:'Wikipedia',url:'https://en.wikipedia.org/wiki/List_of_Scooby-Doo%2C_Where_Are_You%21_episodes'},'sonic-underground':{label:'Wikipedia',url:'https://en.wikipedia.org/wiki/Sonic_Underground'},'sonic-x':{label:'Wikipedia',url:'https://en.wikipedia.org/wiki/List_of_Sonic_X_episodes'},'my-little-pony-friendship-is-magic':{label:'Wikipedia',url:'https://en.wikipedia.org/wiki/List_of_My_Little_Pony:_Friendship_Is_Magic_episodes'}}
function profileColor(profile){let value=0;for(const char of profile.id)value=(value*31+char.charCodeAt(0))>>>0;return colors[value%colors.length]}
function profilePicture(name){return `${import.meta.env.BASE_URL}profiles/${encodeURIComponent(name)}`}
function mediaCrossOrigin(url){try{return new URL(url).hostname.endsWith('.backblazeb2.com')?'anonymous':undefined}catch{return undefined}}
function finishLoading(setter,startedAt){setTimeout(()=>setter(false),Math.max(0,900-(Date.now()-startedAt)))}
function Avatar({profile,add=false}){return <span className={`avatar${add?' add-avatar':''}`} style={add?undefined:{'--avatar-color':profileColor(profile)}} aria-hidden="true">{add?<FontAwesomeIcon icon={faPlus}/>:profile.avatar?<img src={profilePicture(profile.avatar)} alt=""/>:<FontAwesomeIcon className="avatar-face" icon={faFaceSmile}/>}</span>}
function Logo(){return <img className="brand-logo" src={`${import.meta.env.BASE_URL}logo-kingflix.png`} alt="Kingflix"/>}
function LoadingScreen(){return <div className="loading-screen" role="status" aria-live="polite"><Logo/><span>Loading...</span></div>}

function App(){
  const{getToken}=useAuth()
  const[profiles,setProfiles]=useState([]),[profile,setProfile]=useState(null),[profileToken,setProfileToken]=useState('')
  const[view,setView]=useState('select'),[pending,setPending]=useState(null),[pin,setPin]=useState('')
  const[manageToken,setManageToken]=useState('')
  const[picturePicker,setPicturePicker]=useState(null)
  const[form,setForm]=useState({name:'',pin:'',isKids:false,removePin:false,avatar:'bluey.png'})
  const[media,setMedia]=useState([]),[progress,setProgress]=useState([]),[favorites,setFavorites]=useState([]),[selected,setSelected]=useState(null)
  const[error,setError]=useState(''),[busy,setBusy]=useState(false),[profilesLoading,setProfilesLoading]=useState(true),[libraryLoading,setLibraryLoading]=useState(false)
  async function request(path,options={}){const token=await getToken();const response=await fetch(`${api}${path}`,{...options,headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json',...(profileToken?{'X-Profile-Token':profileToken}:{}),...(manageToken?{'X-Manage-Token':manageToken}:{}),...options.headers}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Request failed: ${response.status}`);return data}
  async function loadLibrary(profileId){const items=[];for(let offset=0;;offset+=50){const page=await request(`/api/library?profileId=${encodeURIComponent(profileId)}&limit=50&offset=${offset}`);items.push(...page);if(page.length<50)return items}}
  const enterManage=useReverification(async()=>{const token=await getToken();const response=await fetch(`${api}/api/manage-access`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'}});return response.json()})
  async function updateManagedMedia(id,body){const token=await getToken();const response=await fetch(`${api}/api/manage-media/${encodeURIComponent(id)}`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json','X-Manage-Token':manageToken},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not save video.');return data}
  const updateProfile=useReverification(async(id,body)=>{const token=await getToken();const response=await fetch(`${api}/api/profiles/${id}`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json','X-Profile-Token':profileToken},body:JSON.stringify(body)});return response.json()})
  async function openManage(target='manage'){try{setError('');const result=await enterManage();if(result?.ok){setManageToken(result.token||'');setView(target)}}catch(e){if(e?.name!=='ClerkRuntimeError')setError(e.message||'Password verification was cancelled.')}}
  useEffect(()=>{const startedAt=Date.now();request('/api/profiles').then(setProfiles).catch(e=>setError(e.message)).finally(()=>finishLoading(setProfilesLoading,startedAt))},[])
  useEffect(()=>{if(profile&&profileToken){const startedAt=Date.now();setLibraryLoading(true);Promise.all([loadLibrary(profile.id),request(`/api/progress?profileId=${encodeURIComponent(profile.id)}`),request(`/api/favorites?profileId=${encodeURIComponent(profile.id)}`)]).then(([items,positions,saved])=>{setMedia(items);setProgress(positions);setFavorites(saved.map(item=>item.mediaId))}).catch(e=>setError(e.message)).finally(()=>finishLoading(setLibraryLoading,startedAt))}},[profile,profileToken])
  function resetForm(){setForm({name:'',pin:'',isKids:false,removePin:false,avatar:'bluey.png'})}
  function begin(item,action){setError('');if(item.hasPin){setPending({profile:item,action});setPin('')}else unlock(item,'',action)}
  async function unlock(item,enteredPin,action){try{setBusy(true);setError('');const result=await request(`/api/profiles/${item.id}/unlock`,{method:'POST',body:JSON.stringify({pin:enteredPin}),headers:{'X-Profile-Token':''}});setProfileToken(result.token);setPending(null);setPin('');if(action==='edit'){setProfile(item);setForm({name:item.name,pin:'',isKids:item.isKids,removePin:false,avatar:item.avatar||'bluey.png'});setView('edit')}else{setProfile(item);setView('library')}}catch(e){setError(e.message)}finally{setBusy(false)}}
  async function addProfile(event){event.preventDefault();try{setBusy(true);setError('');const created=await request('/api/profiles',{method:'POST',body:JSON.stringify({name:form.name,pin:form.pin,isKids:form.isKids,avatar:form.avatar})});setProfiles(current=>[...current,created]);resetForm();setView('manage')}catch(e){setError(e.message)}finally{setBusy(false)}}
  async function saveProfile(event){event.preventDefault();try{setBusy(true);setError('');const saved=await updateProfile(profile.id,{name:form.name,isKids:form.isKids,avatar:form.avatar});if(saved?.error)throw new Error(saved.error);let hasPin=form.isKids?false:profile.hasPin;if(!form.isKids&&(form.pin||form.removePin)){const result=await request(`/api/profiles/${profile.id}/pin`,{method:'POST',body:JSON.stringify({pin:form.removePin?'':form.pin})});hasPin=result.hasPin}const updated={...profile,name:form.name.trim(),isKids:form.isKids,avatar:form.avatar,hasPin};setProfiles(current=>current.map(item=>item.id===profile.id?updated:item));setProfile(null);setProfileToken('');resetForm();setView('manage')}catch(e){setError(e.message||'Password verification was cancelled.')}finally{setBusy(false)}}
  async function deleteProfile(){try{setBusy(true);setError('');await request(`/api/profiles/${profile.id}`,{method:'DELETE'});setProfiles(current=>current.filter(item=>item.id!==profile.id));setProfile(null);setProfileToken('');resetForm();setView('manage')}catch(e){setError(e.message)}finally{setBusy(false)}}
  async function play(item,startAt=0){if(item.blocked)return;try{setError('');setSelected({...item,...await request(`/api/media/${item.id}/play`,{method:'POST',body:JSON.stringify({profileId:profile.id})}),startAt})}catch(e){setError(e.message)}}
  async function saveProgress(value){const currentTime=typeof value==='number'?value:value?.target?.currentTime;if(!selected||!profile||!Number.isFinite(currentTime))return;const positionSeconds=Math.floor(currentTime),updatedAt=new Date().toISOString();setProgress(current=>[{mediaId:selected.id,positionSeconds,updatedAt},...current.filter(item=>item.mediaId!==selected.id)]);try{await request('/api/progress',{method:'POST',body:JSON.stringify({profileId:profile.id,mediaId:selected.id,positionSeconds})})}catch(e){setError(e.message)}}
  async function toggleFavorite(mediaId){const saved=favorites.includes(mediaId);setFavorites(current=>saved?current.filter(id=>id!==mediaId):[...current,mediaId]);try{await request('/api/favorites',{method:saved?'DELETE':'POST',body:JSON.stringify({profileId:profile.id,mediaId})})}catch(e){setFavorites(current=>saved?[...current,mediaId]:current.filter(id=>id!==mediaId));setError(e.message)}}
  async function reorderFavorites(fromIndex,toIndex){if(fromIndex===toIndex||fromIndex<0||toIndex<0||fromIndex>=favorites.length||toIndex>=favorites.length)return;const previous=favorites.slice(),next=favorites.slice(),[moved]=next.splice(fromIndex,1);next.splice(toIndex,0,moved);setFavorites(next);try{await request('/api/favorites/reorder',{method:'POST',body:JSON.stringify({profileId:profile.id,mediaIds:next})})}catch(e){setFavorites(previous);setError(e.message)}}
  function choosePicture(item=null){setError('');setPicturePicker({profile:item,value:item?.avatar||form.avatar||'bluey.png'})}
  async function savePicture(){try{setBusy(true);setError('');if(picturePicker.profile){const result=await request(`/api/profiles/${picturePicker.profile.id}/avatar`,{method:'POST',body:JSON.stringify({avatar:picturePicker.value}),headers:{'X-Profile-Token':''}});setProfiles(current=>current.map(item=>item.id===picturePicker.profile.id?{...item,avatar:result.avatar}:item));if(profile?.id===picturePicker.profile.id)setProfile(current=>({...current,avatar:result.avatar}))}else setForm(current=>({...current,avatar:picturePicker.value}));setPicturePicker(null)}catch(e){setError(e.message)}finally{setBusy(false)}}
  function switchProfile(){setProfile(null);setProfileToken('');setSelected(null);setMedia([]);setProgress([]);setFavorites([]);setError('');setView('select')}
  const profilePicker=<div className="profile-groups">{[false,true].map(kids=>{const group=profiles.filter(item=>item.isKids===kids);return group.length?<div className="profile-grid" key={kids?'kids':'adults'}>{group.map(item=><div className="profile-card-wrap" key={item.id}><button className="profile-card" onClick={()=>begin(item,view==='manage'?'edit':'watch')}><span className="avatar-wrap"><Avatar profile={item}/>{item.isKids?<span className="profile-corner" title="Kids profile"><FontAwesomeIcon icon={faChild}/></span>:item.hasPin&&<span className="profile-corner" title="PIN protected"><FontAwesomeIcon icon={faLock}/></span>}{view==='manage'&&<span className="edit-mark"><FontAwesomeIcon icon={faPen}/></span>}</span><span className="profile-name">{item.name}</span></button>{view==='select'&&<button className="avatar-change" type="button" onClick={()=>choosePicture(item)} aria-label={`Change ${item.name}'s profile picture`} title="Change profile picture"><FontAwesomeIcon icon={faCamera}/></button>}</div>)}</div>:null})}</div>
  if(profilesLoading||(view==='library'&&libraryLoading))return <LoadingScreen/>
  return <main className={view==='library'?'home-page':'profile-shell'}>
    {view==='select'&&<header className="site-header"><Logo/><UserButton/></header>}
    {error&&<p role="alert">{error}</p>}
    {view==='select'&&<section className="profile-stage"><h2>Who's watching?</h2>{profilePicker}<div className="manage-buttons"><button className="outline-button icon-button" onClick={()=>openManage('manage')}><FontAwesomeIcon icon={faUsersGear}/>Manage Profiles</button><button className="outline-button icon-button" onClick={()=>openManage('manage-videos')}><FontAwesomeIcon icon={faVideo}/>Manage Videos</button></div></section>}
    {view==='manage'&&<section className="profile-stage"><h2>Manage Profiles</h2>{profilePicker}<button className="profile-card add-card" onClick={()=>{resetForm();setError('');setView('create')}}><Avatar add/><span className="profile-name">Add Profile</span></button><div className="stage-actions"><button className="primary-button" onClick={()=>setView('select')}>Done</button></div></section>}
    {view==='create'&&<ProfileForm title="Add Profile" form={form} setForm={setForm} onSubmit={addProfile} onCancel={()=>{resetForm();setError('');setView('manage')}} onChooseAvatar={()=>choosePicture()} busy={busy}/>}
    {view==='edit'&&<ProfileForm title={`Edit ${profile.name}`} form={form} setForm={setForm} onSubmit={saveProfile} onCancel={()=>{setProfile(null);setProfileToken('');resetForm();setError('');setView('manage')}} onDelete={deleteProfile} onChooseAvatar={()=>choosePicture()} hasPin={profile.hasPin} busy={busy}/>}
    {view==='manage-videos'&&<ManageVideos request={request} save={updateManagedMedia} onDone={()=>{setManageToken('');setView('select')}}/>}
    {picturePicker&&<PicturePicker value={picturePicker.value} setValue={value=>setPicturePicker(current=>({...current,value}))} profileName={picturePicker.profile?.name} onSave={savePicture} onCancel={()=>setPicturePicker(null)} busy={busy}/>}
    {pending&&<div className="modal-backdrop"><form className="dialog" onSubmit={event=>{event.preventDefault();unlock(pending.profile,pin,pending.action)}}><h3>Enter PIN</h3><p>Enter the four digit PIN for {pending.profile.name}.</p><input autoFocus inputMode="numeric" type="password" maxLength="4" pattern="[0-9]{4}" required value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,''))} aria-label="Four digit PIN"/><div className="form-actions"><button className="primary-button" type="submit" disabled={busy}>Continue</button><button type="button" onClick={()=>{setPending(null);setPin('');setError('')}}>Cancel</button></div></form></div>}
    {view==='library'&&<Home media={media} progress={progress} favorites={favorites} toggleFavorite={toggleFavorite} reorderFavorites={reorderFavorites} profile={profile} selected={selected} setSelected={setSelected} play={play} saveProgress={saveProgress} switchProfile={switchProfile}/>}
  </main>
}

function Home({media,progress,favorites,toggleFavorite,reorderFavorites,profile,selected,setSelected,play,saveProgress,switchProfile}){
  const[query,setQuery]=useState(''),[genre,setGenre]=useState(''),[section,setSection]=useState('home'),[selectedSeries,setSelectedSeries]=useState(null),[selectedSeason,setSelectedSeason]=useState(null),[infoId,setInfoId]=useState(null)
  const[showNextCard,setShowNextCard]=useState(false)
  const player=React.useRef(null),lastCheckpoint=React.useRef(0)
  useEffect(()=>{window.history.replaceState({kingVideos:true,section:'home',series:null,season:null,info:null},'');const restore=event=>{if(!event.state?.kingVideos)return;setSection(event.state.section);setSelectedSeries(event.state.series||null);setSelectedSeason(event.state.season??null);setInfoId(event.state.info||null)};window.addEventListener('popstate',restore);return()=>window.removeEventListener('popstate',restore)},[])
  const positions=useMemo(()=>new Map(progress.map(item=>[item.mediaId,item.positionSeconds])),[progress])
  const lastProgress=progress.slice().filter(item=>item.positionSeconds>0).sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')))[0]
  const fallbackFeatured=useMemo(()=>media.length?media[Math.floor(Math.random()*media.length)]:null,[media,profile.id])
  const featured=(lastProgress&&media.find(item=>item.id===lastProgress.mediaId))||fallbackFeatured
  const filtered=media
  const searchMatches=media.filter(item=>[item.title,item.seriesTitle,...(item.genres||[])].filter(Boolean).some(value=>value.toLowerCase().includes(query.toLowerCase())))
  const continuing=filtered.filter(item=>positions.has(item.id))
  const categories=[...new Set(filtered.map(item=>item.category).filter(category=>category&&!/tv|series|show|short/i.test(category)))]
  const tvItems=filtered.filter(item=>/tv|series|show/i.test(item.category))
  const series=useMemo(()=>{const groups=new Map();for(const item of media.filter(item=>/tv|series|show/i.test(item.category)&&item.seriesId)){const group=groups.get(item.seriesId)||[];group.push(item);groups.set(item.seriesId,group)}return groups},[media])
  const nextEpisode=useMemo(()=>{if(!selected?.seriesId)return null;const ordered=(series.get(selected.seriesId)||[]).slice().sort((a,b)=>(a.seasonNumber||0)-(b.seasonNumber||0)||(a.episodeNumber||0)-(b.episodeNumber||0)||a.title.localeCompare(b.title));const index=ordered.findIndex(item=>item.id===selected.id);return index>=0?ordered[index+1]||null:null},[selected,series])
  useEffect(()=>setShowNextCard(false),[selected?.id])
  const tvCards=useMemo(()=>{const grouped=new Map(),standalone=[];for(const item of tvItems){if(!item.seriesId){standalone.push(item);continue}if(!grouped.has(item.seriesId)){const episodes=series.get(item.seriesId)||[item];grouped.set(item.seriesId,{...item,id:`series:${item.seriesId}`,title:item.seriesTitle||item.seriesId,episodeCount:episodes.length,isSeries:true})}}return [...grouped.values(),...standalone]},[tvItems,series])
  const favoriteSet=new Set(favorites)
  const favoriteItems=favorites.map(id=>tvCards.find(item=>item.id===id)||filtered.find(item=>item.id===id)).filter(Boolean)
  const homeRows=[{title:'Continue Watching',items:continuing},{title:'My List',items:favoriteItems},...categories.filter(category=>!/movie/i.test(category)).slice(0,2).map(category=>({title:category,items:/tv|series|show/i.test(category)?tvCards:filtered.filter(item=>item.category===category)}))]
  const newestFirst=(a,b)=>(b.year||0)-(a.year||0)||a.title.localeCompare(b.title)
  const latestAdded=(a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))||a.title.localeCompare(b.title)
  const movies=filtered.filter(item=>!item.category||/movie/i.test(item.category))
  const shorts=filtered.filter(item=>/short/i.test(item.category))
  const movieRows=[{title:'Latest Added',items:movies.slice().sort(latestAdded)},{title:'Release Date · Newest to Oldest',items:movies.slice().sort(newestFirst)}]
  const tvRows=[{title:'Latest Added',items:tvCards.slice().sort(latestAdded)},{title:'Release Date · Newest to Oldest',items:tvCards.slice().sort(newestFirst)}]
  const shortRows=[{title:'Latest Added',items:shorts.slice().sort(latestAdded)},{title:'Release Date · Newest to Oldest',items:shorts.slice().sort(newestFirst)}]
  const matchingSeries=new Set(searchMatches.map(item=>item.seriesId).filter(Boolean))
  const unfilteredSearchItems=[...tvCards.filter(item=>item.isSeries?matchingSeries.has(item.seriesId):searchMatches.some(match=>match.id===item.id)),...searchMatches.filter(item=>!/tv|series|show/i.test(item.category))]
  const searchItems=unfilteredSearchItems.filter(item=>!genre||(item.isSeries?(series.get(item.seriesId)||[]).some(episode=>(episode.genres||[]).includes(genre)):(item.genres||[]).includes(genre)))
  const searchRows=[{title:query?`Results for "${query}"`:'All Titles',items:searchItems}]
  const links=[['home','Home'],['shorts','Shorts'],['movies','Movies'],['tv','TV']]
  function navigate(path,seriesId=null,season=null,info=null){window.history.pushState({kingVideos:true,section:path,series:seriesId,season,info},'');setSelectedSeries(seriesId);setSelectedSeason(season);setInfoId(info);setSection(path)}
  function openMedia(item){navigate('info',null,null,item.id)}
  function openInfo(item){navigate('info',null,null,item.isSeries?item.id:item.id)}
  function checkpoint(){const second=Math.floor(player.current?.currentTime||0);if(second-lastCheckpoint.current>=15){lastCheckpoint.current=second;saveProgress(second)}}
  function savePlayerProgress(){if(player.current)saveProgress(player.current.currentTime)}
  async function exitPlayerFullscreen(){
    const video=player.current?.querySelector?.('video')
    try{
      if(video?.webkitDisplayingFullscreen&&typeof video.webkitExitFullscreen==='function')video.webkitExitFullscreen()
      else if(video?.webkitPresentationMode==='fullscreen'&&typeof video.webkitSetPresentationMode==='function')video.webkitSetPresentationMode('inline')
    }catch{}
    try{
      if(document.fullscreenElement&&typeof document.exitFullscreen==='function')await document.exitFullscreen()
      else if(document.webkitFullscreenElement&&typeof document.webkitExitFullscreen==='function')await document.webkitExitFullscreen()
    }catch{}
  }
  async function finishPlayback(){savePlayerProgress();await exitPlayerFullscreen();setShowNextCard(Boolean(nextEpisode))}
  function closePlayer(){savePlayerProgress();setSelected(null)}
  const episodes=(series.get(selectedSeries)||[]).slice().sort((a,b)=>(a.seasonNumber||0)-(b.seasonNumber||0)||(a.episodeNumber||0)-(b.episodeNumber||0)||a.title.localeCompare(b.title))
  const infoItem=tvCards.find(item=>item.id===infoId)||media.find(item=>item.id===infoId)
  const infoIsSeries=Boolean(infoItem&&(infoItem.isSeries||String(infoItem.id).startsWith('series:')))
  const infoEpisodes=infoItem?.seriesId?(series.get(infoItem.seriesId)||[]).slice().sort((a,b)=>(a.seasonNumber||0)-(b.seasonNumber||0)||(a.episodeNumber||0)-(b.episodeNumber||0)||a.title.localeCompare(b.title)):[]
  const watchedInfoEpisode=infoEpisodes.length?progress.map(entry=>infoEpisodes.find(item=>item.id===entry.mediaId)).find(Boolean):null
  const infoPlayable=infoIsSeries?(watchedInfoEpisode||infoEpisodes[0]):infoItem
  const infoPosition=infoPlayable?positions.get(infoPlayable.id)||0:0
  const nextInfoStart=infoEpisodes.findIndex(item=>item.id===infoPlayable?.id)+1
  const nextInfoEpisodes=infoEpisodes.length?infoEpisodes.slice(Math.max(0,nextInfoStart),Math.max(0,nextInfoStart)+12):[]
  const similarTitles=infoItem&&!infoItem.seriesId&&!infoItem.isSeries?media.filter(item=>item.id!==infoItem.id&&(infoItem.category==='short'?item.category==='short':/movie/i.test(item.category||'movie'))).map(item=>({...item,matchCount:(item.genres||[]).filter(genre=>(infoItem.genres||[]).includes(genre)).length})).filter(item=>item.matchCount>0).sort((a,b)=>b.matchCount-a.matchCount||(b.year||0)-(a.year||0)).slice(0,12):[]
  const infoRelatedRows=infoIsSeries?[...new Set(infoEpisodes.map(item=>item.seasonNumber??1))].sort((a,b)=>a-b).map(season=>({title:season===0?'Shorts':`Season ${season}`,items:infoEpisodes.filter(item=>(item.seasonNumber??1)===season)})):[{title:infoItem?.seriesId?'Next Episodes':infoItem?.category==='short'?'Similar Shorts':'Similar Movies',items:infoItem?.seriesId?nextInfoEpisodes:similarTitles}]
  return <><header className="home-header"><Logo/><nav>{links.map(([path,label])=><button key={path} className={section===path?'active':''} onClick={()=>navigate(path)}>{label}</button>)}<button className={section==='search'?'active':''} onClick={()=>navigate('search')}><FontAwesomeIcon icon={faMagnifyingGlass}/> Search</button></nav><button className="active-profile" onClick={switchProfile} aria-label={`Switch from ${profile.name}`}><Avatar profile={profile}/></button></header>
    {section==='home'&&<><Hero featured={featured} position={lastProgress?.positionSeconds||0} hasProgress={Boolean(lastProgress)} play={play} info={openInfo} series={featured?.seriesId?()=>navigate('series',featured.seriesId):null}/><Shelves rows={homeRows} media={media} positions={positions} favorites={favoriteSet} toggleFavorite={toggleFavorite} reorderFavorites={reorderFavorites} onEmptyMyList={()=>navigate('search')} play={openMedia}/></>}
    {section==='movies'&&<BrowsePage title="Movies" rows={movieRows} media={media} positions={positions} favorites={favoriteSet} toggleFavorite={toggleFavorite} play={openMedia}/>}
    {section==='tv'&&<BrowsePage title="TV" rows={tvRows} media={media} positions={positions} favorites={favoriteSet} toggleFavorite={toggleFavorite} play={openMedia}/>}
    {section==='shorts'&&<BrowsePage title="Shorts" rows={shortRows} media={media} positions={positions} favorites={favoriteSet} toggleFavorite={toggleFavorite} play={openMedia}/>}
    {section==='series'&&<SeriesPage series={episodes} selectedSeason={selectedSeason} positions={positions} play={openMedia} onBack={()=>window.history.back()} onSelectSeason={season=>navigate('series',selectedSeries,season)}/>}
    {section==='info'&&infoItem&&<DetailsPage item={infoItem} playable={infoPlayable} position={infoPosition} relatedRows={infoRelatedRows} positions={positions} favorites={favoriteSet} saved={favoriteSet.has(infoItem.id)} play={play} openDetails={openMedia} openSeries={()=>navigate('series',infoItem.seriesId)} toggleFavorite={toggleFavorite} onBack={()=>window.history.back()}/>}
    {section==='search'&&<><section className="search-page"><div className="home-search"><FontAwesomeIcon icon={faMagnifyingGlass}/><input autoFocus aria-label="Search videos" placeholder="Search titles" value={query} onChange={event=>setQuery(event.target.value)}/></div><GenreFilters selected={genre} setSelected={setGenre}/></section><SearchGrid title={searchRows[0].title} query={`${query}|${genre}`} items={searchItems} positions={positions} favorites={favoriteSet} toggleFavorite={toggleFavorite} play={openMedia}/></>}
    {selected&&<section className="player-overlay"><div className="player-bar"><h2>{selected.title}</h2><button className="icon-button" onClick={closePlayer}><FontAwesomeIcon icon={faXmark}/>Close</button></div><div className="player-stage"><MediaPlayer key={selected.id} ref={player} title={selected.title} src={{src:selected.url,type:selected.mimeType||'video/mp4'}} autoPlay playsInline load="eager" crossOrigin={mediaCrossOrigin(selected.url)} onLoadedMetadata={()=>{if(player.current)player.current.currentTime=selected.startAt||0;lastCheckpoint.current=Math.floor(selected.startAt||0)}} onTimeUpdate={checkpoint} onPlay={()=>setShowNextCard(false)} onPause={savePlayerProgress} onEnded={finishPlayback} onSeeked={savePlayerProgress}><MediaProvider>{selected.subtitleUrl&&<Track default src={selected.subtitleUrl} kind="subtitles" label="English" lang="en" type="vtt"/>}</MediaProvider><DefaultVideoLayout icons={defaultLayoutIcons}/></MediaPlayer>{showNextCard&&nextEpisode&&<button className="next-episode-card" onClick={()=>play(nextEpisode)} aria-label={`Play next episode: ${nextEpisode.title}`}><span className="next-episode-label">Up next</span>{nextEpisode.thumbnailUrl?<img src={nextEpisode.thumbnailUrl} alt=""/>:<span className="next-episode-placeholder"><FontAwesomeIcon icon={faPlay}/></span>}<span className="next-episode-copy"><small>{nextEpisode.seasonNumber?`Season ${nextEpisode.seasonNumber} · `:''}Episode {nextEpisode.episodeNumber||''}</small><strong>{nextEpisode.title}</strong><span><FontAwesomeIcon icon={faPlay}/> Play next episode</span></span></button>}</div></section>}
  </>
}

function Hero({featured,position,hasProgress,play,info,series}){return featured&&<section className="hero" style={featured.thumbnailUrl?{'--hero-image':`url("${featured.thumbnailUrl}")`}:undefined}><div className="hero-content"><small>{hasProgress?'Continue Watching':'Featured'}</small><h1>{featured.seriesTitle||featured.title}</h1>{featured.seriesTitle&&<h2>{featured.title}</h2>}<p>{featured.description||'Watch on King Videos.'}</p><div><button className="hero-play icon-button" disabled={featured.blocked} onClick={()=>play(featured,position)}><FontAwesomeIcon icon={featured.blocked?faLock:faPlay}/>{featured.blocked?'Blocked':hasProgress?'Continue':'Play'}</button>{hasProgress&&!featured.blocked&&<button className="hero-info icon-button" onClick={()=>play(featured,0)}><FontAwesomeIcon icon={faPlay}/>Restart</button>}<button className="hero-info icon-button" onClick={()=>info(featured)}><FontAwesomeIcon icon={faCircleInfo}/>Info</button>{series&&<button className="hero-info icon-button" onClick={series}><FontAwesomeIcon icon={faVideo}/>Series</button>}</div></div></section>}
function DetailsPage({item,playable,position,relatedRows,positions,favorites,saved,play,openDetails,openSeries,toggleFavorite,onBack}){const isSeriesDetail=item.isSeries||String(item.id).startsWith('series:'),hasProgress=position>0,title=isSeriesDetail?(item.seriesTitle||item.title):item.title,blocked=Boolean(playable?.blocked);return <section className="details-page"><div className="info-page" style={item.thumbnailUrl?{'--info-image':`url("${item.thumbnailUrl}")`}:undefined}><button className="series-back icon-button" onClick={onBack}><FontAwesomeIcon icon={faArrowLeft}/>Back</button><div className="info-content"><small>{isSeriesDetail?'TV Series':item.category||'Movie'}</small><h1>{title}</h1><div className="title-meta">{item.year&&<span>{item.year}</span>}{item.rating&&<span>{item.rating}</span>}{isSeriesDetail&&<span>{item.episodeCount} episodes</span>}{!isSeriesDetail&&item.durationSeconds&&<span>{formatDuration(item.durationSeconds)}</span>}{blocked&&<span className="blocked-label"><FontAwesomeIcon icon={faLock}/> Blocked</span>}</div><p>{item.description||'Watch on King Videos.'}</p>{blocked&&<p className="blocked-note">Blocked — this title is waiting to be watched together before playback is enabled.</p>}{item.genres?.length>0&&<div className="genre-list">{item.genres.map(genre=><span key={genre}>{genre}</span>)}</div>}<div className="info-actions">{!isSeriesDetail&&playable&&<button className="hero-play icon-button" disabled={blocked} onClick={()=>play(playable,position)}><FontAwesomeIcon icon={blocked?faLock:faPlay}/>{blocked?'Blocked':hasProgress?'Continue':'Watch'}</button>}{!isSeriesDetail&&playable&&hasProgress&&!blocked&&<button className="hero-info icon-button" onClick={()=>play(playable,0)}><FontAwesomeIcon icon={faPlay}/>Restart</button>}{item.seriesId&&<button className="hero-info icon-button" onClick={openSeries}><FontAwesomeIcon icon={faCircleInfo}/>View Seasons</button>}{canAddToList(item)&&<button className="hero-info icon-button" onClick={()=>toggleFavorite(item.id)}><FontAwesomeIcon icon={saved?faCheck:faPlus}/>{saved?'In My List':'Add to My List'}</button>}</div></div></div>{relatedRows.some(row=>row.items.length>0)&&<div className="details-related">{relatedRows.filter(row=>row.items.length>0).map(row=><MediaRow key={row.title} title={row.title} items={row.items} positions={positions} favorites={favorites} toggleFavorite={toggleFavorite} play={openDetails}/>)}</div>}</section>}
function Shelves({rows,media,positions,favorites,toggleFavorite,reorderFavorites,onEmptyMyList,play}){const visible=rows.filter(row=>row.items.length||row.title==='My List'||row.title==='Continue Watching');return <div className="shelves">{visible.map(row=><MediaRow key={row.title} title={row.title} items={row.items} positions={positions} favorites={favorites} toggleFavorite={toggleFavorite} reorderFavorites={reorderFavorites} onEmptyMyList={onEmptyMyList} play={play}/>)}{!media.length&&<p className="empty-library">No videos yet. Add a video to the catalog to begin.</p>}</div>}
function BrowsePage({title,rows,media,positions,favorites,toggleFavorite,play}){return <><section className="browse-heading"><h1>{title}</h1></section><Shelves rows={rows} media={media} positions={positions} favorites={favorites} toggleFavorite={toggleFavorite} play={play}/></>}

function formatDuration(seconds){if(!seconds)return '';const minutes=Math.round(seconds/60),hours=Math.floor(minutes/60),remaining=minutes%60;return hours?`${hours}h${remaining?` ${remaining}m`:''}`:`${minutes}m`}
function canAddToList(item){return Boolean(item&&(item.isSeries||String(item.id).startsWith('series:')||(!item.seriesId&&/movie/i.test(item.category||'movie'))))}
function MediaCard({item,position,favorite,toggleFavorite,play,search=false,reorder,dragging=false,cardRef,dragProps}){const details=[item.rating,item.year,item.isSeries?`${item.episodeCount} episodes`:formatDuration(item.durationSeconds)].filter(Boolean),synopsis=item.description||'Watch on King Videos.',watched=position===undefined?null:item.durationSeconds?Math.min(100,Math.max(0,position/item.durationSeconds*100)):Math.min(92,Math.max(8,position/60));return <article ref={cardRef} id={`media-${item.id}`} className={`shelf-card${search?' search-card':''}${reorder?' reorderable':''}${dragging?' dragging':''}${item.blocked?' blocked':''}`} {...dragProps}><button className="card-main" onClick={()=>play(item)}><span className="card-art">{item.thumbnailUrl?<img loading="lazy" decoding="async" src={item.thumbnailUrl} alt=""/>:<span className="poster-placeholder"><FontAwesomeIcon icon={faPlay}/></span>}{item.blocked&&<span className="card-blocked"><FontAwesomeIcon icon={faLock}/> Blocked</span>}{watched!==null&&<span className="watch-progress" style={{'--watched':`${watched}%`}}/>}<strong title={item.title}>{item.title}</strong></span><span className="card-details">{details.join(' • ')||item.category||'Video'}</span><span className="card-synopsis" title={synopsis}>{synopsis}</span></button>{canAddToList(item)&&<button className={`favorite-button${favorite?' saved':''}`} onClick={()=>toggleFavorite(item.id)} aria-label={`${favorite?'Remove from':'Add to'} My List`} title={`${favorite?'Remove from':'Add to'} My List`}><FontAwesomeIcon icon={favorite?faCheck:faPlus}/></button>}{reorder&&<div className="reorder-controls"><button type="button" onClick={()=>reorder.move(-1)} disabled={reorder.index===0} aria-label={`Move ${item.title} left`}><FontAwesomeIcon icon={faChevronLeft}/></button><span title="Drag to reorder"><FontAwesomeIcon icon={faGripVertical}/></span><button type="button" onClick={()=>reorder.move(1)} disabled={reorder.index===reorder.total-1} aria-label={`Move ${item.title} right`}><FontAwesomeIcon icon={faChevronRight}/></button></div>}</article>}

function SearchGrid({title,query,items,positions,favorites,toggleFavorite,play}){const[visibleCount,setVisibleCount]=useState(24),sentinel=React.useRef(null);useEffect(()=>setVisibleCount(24),[query]);useEffect(()=>{const node=sentinel.current;if(!node||visibleCount>=items.length)return;const observer=new IntersectionObserver(entries=>{if(entries[0].isIntersecting)setVisibleCount(count=>Math.min(count+24,items.length))},{rootMargin:'500px'});observer.observe(node);return()=>observer.disconnect()},[visibleCount,items.length]);const visible=items.slice(0,visibleCount);return <section className="search-results"><h2>{title}</h2>{visible.length?<div className="search-grid">{visible.map(item=><MediaCard key={item.id} item={item} position={positions.get(item.id)} favorite={favorites.has(item.id)} toggleFavorite={toggleFavorite} play={play} search/>)}</div>:<p className="empty-search">No titles match your search.</p>}<div className="search-sentinel" ref={sentinel}>{visibleCount<items.length?'Loading more…':''}</div></section>}

function GenreFilters({selected,setSelected}){return <div className="genre-filters" aria-label="Filter by genre"><button className={!selected?'active':''} onClick={()=>setSelected('')}>All</button>{genres.map(item=><button className={selected===item?'active':''} key={item} onClick={()=>setSelected(item)}>{item}</button>)}</div>}

function SeriesPage({series,selectedSeason,positions,play,onBack,onSelectSeason}){const show=series[0];if(!show)return null;const seasonName=season=>season===0?'Shorts':`Season ${season}`,seasons=[...new Set(series.map(item=>item.seasonNumber??1))].sort((a,b)=>a-b),episodes=selectedSeason===null?[]:series.filter(item=>(item.seasonNumber??1)===selectedSeason),credit=seriesCredits[show.seriesId];return <section className="series-page"><button className="series-back icon-button" onClick={onBack}><FontAwesomeIcon icon={faArrowLeft}/>{selectedSeason===null?'Back to TV':`Back to ${show.seriesTitle||show.seriesId}`}</button>{selectedSeason===null?<><header className="series-intro">{show.thumbnailUrl&&<img src={show.thumbnailUrl} alt=""/>}<div><small>TV Series</small><h1>{show.seriesTitle||show.seriesId}</h1><p>{show.description}</p><span>{seasons.length} season{seasons.length===1?'':'s'} • {series.length} episodes{show.rating?` • ${show.rating}`:''}</span></div></header><h2>Seasons</h2><div className="season-grid">{seasons.map(season=>{const count=series.filter(item=>(item.seasonNumber??1)===season).length;return <button className="season-card" key={season} onClick={()=>onSelectSeason(season)}>{show.thumbnailUrl?<img src={show.thumbnailUrl} alt=""/>:<span className="poster-placeholder"><FontAwesomeIcon icon={faPlay}/></span>}<span><strong>{seasonName(season)}</strong><small>{count} episode{count===1?'':'s'}</small></span></button>})}</div></>:<><header className="season-heading"><small>{show.seriesTitle||show.seriesId}</small><h1>{seasonName(selectedSeason)}</h1><span>{episodes.length} episode{episodes.length===1?'':'s'}</span></header><div className="episode-grid">{episodes.map(item=><button className="episode-card" key={item.id} onClick={()=>play(item)}>{item.thumbnailUrl?<img src={item.thumbnailUrl} alt=""/>:<span className="poster-placeholder"><FontAwesomeIcon icon={faPlay}/></span>}{positions.has(item.id)&&<span className="watch-progress" style={{'--watched':`${Math.min(92,Math.max(8,positions.get(item.id)/60))}%`}}/>}<span className="episode-copy"><small>{selectedSeason===0?'Short':`Episode ${item.episodeNumber||''}`}</small><strong>{item.title}</strong><span>{item.description}</span></span></button>)}</div></>}{credit&&<p className="metadata-credit">Episode descriptions from <a href={credit.url} target="_blank" rel="noreferrer">{credit.label}</a>, available under CC BY-SA.</p>}</section>}

function MediaRow({title,items,positions,favorites,toggleFavorite,reorderFavorites,onEmptyMyList,play}){
  const track=React.useRef(null),snapTimer=React.useRef(null),cardRefs=React.useRef(new Map()),dragOrigin=React.useRef(null),dragGhost=React.useRef(null),dragOffset=React.useRef({x:0,y:0})
  const[edges,setEdges]=useState({start:true,end:true}),[draggedId,setDraggedId]=useState(null),[previewItems,setPreviewItems]=useState(items),isMyList=title==='My List'
  useEffect(()=>{if(!draggedId)setPreviewItems(items)},[items,draggedId])
  useEffect(()=>{const node=track.current;if(!node)return;const measure=()=>{const first=node.firstElementChild,last=node.lastElementChild,viewport=node.getBoundingClientRect(),firstBox=first?.getBoundingClientRect(),lastBox=last?.getBoundingClientRect();return{start:!firstBox||firstBox.right>viewport.left+2,end:!lastBox||lastBox.left<viewport.right-2,max:Math.max(0,node.scrollWidth-node.clientWidth)}},update=()=>{const{start,end}=measure();setEdges({start,end})},settle=()=>{clearTimeout(snapTimer.current);snapTimer.current=setTimeout(()=>{const{start,end,max}=measure();if(start&&node.scrollLeft>1)node.scrollTo({left:0,behavior:'smooth'});else if(end&&max-node.scrollLeft>1)node.scrollTo({left:max,behavior:'smooth'})},140)},onScroll=()=>{update();settle()};update();node.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',update);return()=>{clearTimeout(snapTimer.current);node.removeEventListener('scroll',onScroll);window.removeEventListener('resize',update)}},[items.length,title])
  const cardPositions=()=>new Map([...cardRefs.current].map(([id,node])=>[id,node?.getBoundingClientRect()]))
  function animateCards(before,duration,skipId=null){requestAnimationFrame(()=>requestAnimationFrame(()=>{for(const[id,node]of cardRefs.current){if(!node||id===skipId)continue;const old=before.get(id),now=node.getBoundingClientRect(),x=(old?.left||now.left)-now.left;if(Math.abs(x)>1)node.animate([{transform:`translateX(${x}px)`},{transform:'translateX(0)'}],{duration,easing:'cubic-bezier(.22,1,.36,1)'})}}))}
  function previewMove(targetId,pointerX){if(!draggedId||draggedId===targetId)return;const from=previewItems.findIndex(item=>item.id===draggedId),to=previewItems.findIndex(item=>item.id===targetId),targetBox=cardRefs.current.get(targetId)?.getBoundingClientRect();if(from<0||to<0||from===to||targetBox&&(from<to&&pointerX<targetBox.left+targetBox.width*.3||from>to&&pointerX>targetBox.left+targetBox.width/2))return;const before=cardPositions(),next=previewItems.slice(),[moved]=next.splice(from,1);next.splice(to,0,moved);setPreviewItems(next);animateCards(before,320,draggedId)}
  function buttonMove(index,direction){const target=index+direction;if(target<0||target>=displayed.length)return;const before=cardPositions();reorderFavorites(index,target);animateCards(before,650)}
  function moveDragGhost(event){if(!dragGhost.current||!event.clientX&&!event.clientY)return;dragGhost.current.style.left=`${event.clientX-dragOffset.current.x}px`;dragGhost.current.style.top=`${event.clientY-dragOffset.current.y}px`}
  function finishDrag(save=true){if(save&&dragOrigin.current!==null&&draggedId){const target=previewItems.findIndex(item=>item.id===draggedId);if(target>=0&&target!==dragOrigin.current)reorderFavorites(dragOrigin.current,target)}dragGhost.current?.remove();dragGhost.current=null;dragOrigin.current=null;setDraggedId(null)}
  const displayed=isMyList?previewItems:items
  return <section className="shelf"><h2>{title}</h2>{edges.end&&!edges.start&&<span aria-hidden="true" className="shelf-arrow shelf-arrow-left"><FontAwesomeIcon icon={faChevronLeft}/></span>}<div className="shelf-track" ref={track}>{displayed.map((item,index)=><MediaCard key={item.id} item={item} position={positions.get(item.id)} favorite={favorites.has(item.id)} toggleFavorite={toggleFavorite} play={play} reorder={isMyList?{index,total:displayed.length,move:direction=>buttonMove(index,direction)}:null} dragging={draggedId===item.id} cardRef={isMyList?node=>{if(node)cardRefs.current.set(item.id,node);else cardRefs.current.delete(item.id)}:undefined} dragProps={isMyList?{draggable:true,onDragStart:event=>{event.dataTransfer.effectAllowed='move';const ghost=event.currentTarget.cloneNode(true),box=event.currentTarget.getBoundingClientRect(),offsetX=event.clientX-box.left,offsetY=event.clientY-box.top,blank=document.createElement('canvas');blank.width=blank.height=1;event.dataTransfer.setDragImage(blank,0,0);dragOffset.current={x:offsetX,y:offsetY};ghost.classList.remove('dragging');ghost.style.cssText=`position:fixed;z-index:10000;pointer-events:none;left:${event.clientX-offsetX}px;top:${event.clientY-offsetY}px;width:${box.width}px;opacity:1;transform:scale(1.09) rotate(-1deg);transform-origin:${offsetX}px ${offsetY}px;border:2px solid #e7ad35;box-shadow:0 24px 55px #000e;filter:brightness(1.05);`;document.body.appendChild(ghost);dragGhost.current=ghost;dragOrigin.current=items.findIndex(entry=>entry.id===item.id);setPreviewItems(items);setDraggedId(item.id)},onDrag:moveDragGhost,onDragEnd:()=>finishDrag(false),onDragEnter:event=>previewMove(item.id,event.clientX),onDragOver:event=>{event.preventDefault();event.dataTransfer.dropEffect='move';moveDragGhost(event)},onDrop:event=>{event.preventDefault();finishDrag(true)}}:undefined}/>)}{title==='Continue Watching'&&!items.length&&<div className="empty-row-card">Nothing here yet</div>}{isMyList&&<button className="empty-list-button" onClick={onEmptyMyList}><span><FontAwesomeIcon icon={faPlus}/></span>Add to My List</button>}</div>{edges.start&&!edges.end&&<span aria-hidden="true" className="shelf-arrow shelf-arrow-right"><FontAwesomeIcon icon={faChevronRight}/></span>}</section>
}

function ManageVideos({request,save,onDone}){
  const[query,setQuery]=useState(''),[items,setItems]=useState([]),[editing,setEditing]=useState(null),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[message,setMessage]=useState('')
  async function search(event){event?.preventDefault();try{setLoading(true);setMessage('');setEditing(null);setItems(await request(`/api/manage-media?q=${encodeURIComponent(query)}&limit=50`))}catch(error){setMessage(error.message)}finally{setLoading(false)}}
  useEffect(()=>{search()},[])
  function edit(item){setMessage('');setEditing({...item,rating:item.rating||'',genres:item.genres||[]})}
  function toggleGenre(genre){setEditing(current=>({...current,genres:current.genres.includes(genre)?current.genres.filter(item=>item!==genre):[...current.genres,genre]}))}
  async function submit(event){event.preventDefault();try{setSaving(true);setMessage('');const updated=await save(editing.id,{title:editing.title,description:editing.description,rating:editing.rating,kids:editing.kids,blocked:editing.blocked,genres:editing.genres});setItems(current=>current.map(item=>item.id===editing.id?{...item,...updated}:item));setEditing(current=>({...current,...updated}));setMessage('Video saved.')}catch(error){if(error?.name!=='ClerkRuntimeError')setMessage(error.message||'Password verification was cancelled.')}finally{setSaving(false)}}
  return <section className="manage-videos"><header><div><small>Library administration</small><h2>Manage Videos</h2></div><button className="primary-button" onClick={onDone}>Done</button></header><form className="manage-video-search" onSubmit={search}><FontAwesomeIcon icon={faMagnifyingGlass}/><input autoFocus value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search titles or series" aria-label="Search videos"/><button type="submit">Search</button></form>{message&&<p className="manage-message" role="status">{message}</p>}{editing?<form className="video-editor" onSubmit={submit}><button className="series-back icon-button" type="button" onClick={()=>{setEditing(null);setMessage('')}}><FontAwesomeIcon icon={faArrowLeft}/>Back to results</button><div className="video-editor-heading">{editing.thumbnailUrl&&<img src={editing.thumbnailUrl} alt=""/>}<div><small>{editing.seriesTitle?`${editing.seriesTitle}${editing.seasonNumber?` · Season ${editing.seasonNumber}`:''}${editing.episodeNumber?` · Episode ${editing.episodeNumber}`:''}`:editing.category}</small><h3>{editing.title}</h3></div></div><label>Title<input required maxLength="200" value={editing.title} onChange={event=>setEditing(current=>({...current,title:event.target.value}))}/></label><label>Description<textarea rows="6" maxLength="4000" value={editing.description||''} onChange={event=>setEditing(current=>({...current,description:event.target.value}))}/></label><label>Rating<select value={editing.rating} onChange={event=>setEditing(current=>({...current,rating:event.target.value}))}><option value="">Unrated</option>{['G','PG','PG-13','R','NC-17','TV-Y','TV-Y7','TV-G','TV-PG','TV-14','TV-MA'].map(rating=><option key={rating}>{rating}</option>)}</select></label><fieldset><legend>Genres</legend><div className="genre-editor">{genres.map(genre=><button type="button" key={genre} className={editing.genres.includes(genre)?'selected':''} onClick={()=>toggleGenre(genre)} aria-pressed={editing.genres.includes(genre)}>{genre}</button>)}</div></fieldset><label className="toggle-row"><span><strong>Available to kids</strong><small>Show this title on kids profiles.</small></span><input type="checkbox" checked={editing.kids} onChange={event=>setEditing(current=>({...current,kids:event.target.checked}))}/></label><label className="toggle-row blocked-toggle"><span><strong>Blocked</strong><small>Keep the details visible, but disable playback until you unblock it.</small></span><input type="checkbox" checked={editing.blocked} onChange={event=>setEditing(current=>({...current,blocked:event.target.checked}))}/></label><div className="form-actions"><button className="primary-button" type="submit" disabled={saving}>{saving?'Saving...':'Save Video'}</button><button type="button" onClick={()=>setEditing(null)} disabled={saving}>Cancel</button></div></form>:loading?<LoadingScreen/>:<div className="manage-video-grid">{items.map(item=><button key={item.id} className={`manage-video-card${item.blocked?' blocked':''}`} onClick={()=>edit(item)}>{item.thumbnailUrl?<img src={item.thumbnailUrl} alt=""/>:<span className="poster-placeholder"><FontAwesomeIcon icon={faVideo}/></span>}<span><strong>{item.title}</strong><small>{[item.seriesTitle,item.rating,item.year].filter(Boolean).join(' · ')}</small>{item.blocked&&<b><FontAwesomeIcon icon={faLock}/> Blocked</b>}</span><FontAwesomeIcon className="manage-edit-icon" icon={faPen}/></button>)}</div>}</section>
}

function PicturePicker({value,setValue,profileName,onSave,onCancel,busy}){return <div className="modal-backdrop"><div className="dialog picture-dialog" role="dialog" aria-modal="true" aria-labelledby="picture-title"><h3 id="picture-title">Choose {profileName?`${profileName}'s `:''}profile picture</h3><div className="avatar-picker">{profilePictures.map(picture=><button key={picture} type="button" className={value===picture?'selected':''} onClick={()=>setValue(picture)} aria-label={`Use ${picture.replace(/\.[^.]+$/,'')} profile picture`} aria-pressed={value===picture}><img src={profilePicture(picture)} alt=""/>{value===picture&&<FontAwesomeIcon icon={faCheck}/>}</button>)}</div><div className="form-actions"><button className="primary-button" type="button" onClick={onSave} disabled={busy}>{busy?'Saving...':'Use Picture'}</button><button type="button" onClick={onCancel} disabled={busy}>Cancel</button></div></div></div>}
function ProfileForm({title,form,setForm,onSubmit,onCancel,onDelete,onChooseAvatar,hasPin=false,busy}){const[confirmDelete,setConfirmDelete]=useState(false);const change=values=>setForm(current=>({...current,...values}));return <form className="profile-form" onSubmit={onSubmit}><h2>{title}</h2><div className="profile-picture-field"><Avatar profile={{id:'profile-preview',avatar:form.avatar}}/><div><strong>Profile picture</strong><button className="outline-button icon-button" type="button" onClick={onChooseAvatar}><FontAwesomeIcon icon={faCamera}/>Choose Picture</button></div></div><label>Profile name<input autoFocus maxLength="40" required value={form.name} onChange={e=>change({name:e.target.value})}/></label><label className="check"><input type="checkbox" checked={form.isKids} onChange={e=>change({isKids:e.target.checked,pin:'',removePin:e.target.checked&&hasPin})}/><span><strong><FontAwesomeIcon icon={faChild}/> Kids profile</strong><small>Only videos marked as suitable for kids will appear. Kids profiles cannot have a PIN.</small></span></label>{!form.isKids&&<><label><FontAwesomeIcon icon={faLock}/> {hasPin?'New PIN':'Optional PIN'}<input inputMode="numeric" type="password" maxLength="4" pattern="[0-9]{4}" value={form.pin} disabled={form.removePin} onChange={e=>change({pin:e.target.value.replace(/\D/g,'')})} placeholder={hasPin?'Leave blank to keep current PIN':'Four digits'}/></label>{hasPin&&<label className="check"><input type="checkbox" checked={form.removePin} onChange={e=>change({removePin:e.target.checked,pin:''})}/><span><strong><FontAwesomeIcon icon={faXmark}/> Remove PIN</strong><small>Anyone using this account will be able to open the profile.</small></span></label>}</>}<div className="form-actions"><button className="primary-button" type="submit" disabled={busy}>{busy?'Saving...':'Save'}</button><button type="button" onClick={onCancel}>Cancel</button>{onDelete&&<button className="danger-button icon-button" type="button" onClick={()=>setConfirmDelete(true)} disabled={busy}><FontAwesomeIcon icon={faTrashCan}/>Delete Profile</button>}</div>{confirmDelete&&<div className="modal-backdrop"><div className="dialog confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="delete-title"><FontAwesomeIcon className="warning-icon" icon={faTriangleExclamation}/><h3 id="delete-title">Are you sure?</h3><p>Delete <strong>{form.name}</strong>? This will permanently delete the profile and its viewing progress.</p><div className="form-actions"><button type="button" onClick={()=>setConfirmDelete(false)} autoFocus>Cancel</button><button className="danger-button icon-button" type="button" onClick={onDelete} disabled={busy}><FontAwesomeIcon icon={faTrashCan}/>{busy?'Deleting...':'Delete Profile'}</button></div></div></div>}</form>}
const appUrl=`${window.location.origin}${import.meta.env.BASE_URL}`
createRoot(document.getElementById('root')).render(key&&api?<ClerkProvider publishableKey={key}><SignedOut><main className="signed-out"><Logo/><p>Your private video library.</p><SignIn routing="hash" fallbackRedirectUrl={appUrl}/></main></SignedOut><SignedIn><App/></SignedIn></ClerkProvider>:<main className="signed-out"><Logo/><p>Set VITE_CLERK_PUBLISHABLE_KEY and VITE_API_URL to configure this app.</p></main>)
